class Solution { public String tictactoe(int[][] moves){int[] rows=new int[3],columns=new int[3];int diagonal=0,antiDiagonal=0;for(int i=0;i<moves.length;i++){int score=i%2==0?1:-1,r=moves[i][0],c=moves[i][1];rows[r]+=score;columns[c]+=score;if(r==c)diagonal+=score;if(r+c==2)antiDiagonal+=score;if(Math.abs(rows[r])==3||Math.abs(columns[c])==3||Math.abs(diagonal)==3||Math.abs(antiDiagonal)==3)return score==1?"A":"B";}return moves.length==9?"Draw":"Pending";} }
